; Sets [0x23]=1 if HERO_Y < [0x41], else [0x23]=0. The
; hero-camera-relationship gate used by
; CAVES_REPAINT_BACKDROP_IF_SCREEN_CHANGED and other CAVES routines.
CHECK_HERO_Y_LT_VAR41:
	mov [0x23], 0x0001
	jl [HERO_Y], [0x41], LABEL_DA0E
	mov [0x23], 0x0000

LABEL_DA0E:
	ret


LABEL_DA0F:
	mov [HERO_Y], [0x40]
	je [0x23], 0x00, LABEL_DA1B
	mov [HERO_Y], [0x44]

LABEL_DA1B:
	ret


