	je [SCREEN_NUM], 0xCC, LABEL_DA3A
	je [SCREEN_NUM], 0xC8, LABEL_DA3A
	je [SCREEN_NUM], 0x6B, LABEL_DA3A
	mov [HERO_Y], [0x40]
	je [0x23], 0x00, LABEL_DA3A
	mov [HERO_Y], [0x44]

LABEL_DA3A:
	call CAVES_COPY_VAR40_TO_VAR22_L3
	jl [HERO_Y], [0x22], CAVES_NOOP_RET
	mov [HERO_Y], [0x22]
	ret


